"""Tests for security features.

Ported from handlebars.js spec/security.js, adapted for Python.
"""

from datetime import datetime

import pytest

from pydantic_handlebars import HandlebarsRuntimeError, render

# --- Dunder keys in dicts are now normal keys (serialization makes them safe) ---


def test_dunder_class_key_renders():
    assert render('{{__class__}}', {'__class__': 'hacked'}) == 'hacked'


def test_dunder_dict_key_renders():
    assert render('{{obj.__dict__}}', {'obj': {'__dict__': 'hacked'}}) == 'hacked'


def test_dunder_globals_key_renders():
    assert render('{{__globals__}}', {'__globals__': 'hacked'}) == 'hacked'


def test_dunder_init_key_renders():
    assert render('{{obj.__init__}}', {'obj': {'__init__': 'hacked'}}) == 'hacked'


def test_dunder_module_key_renders():
    assert render('{{__module__}}', {'__module__': 'hacked'}) == 'hacked'


def test_dunder_subclasses_key_renders():
    assert render('{{__subclasses__}}', {'__subclasses__': 'hacked'}) == 'hacked'


def test_constructor_key_renders():
    assert render('{{constructor}}', {'constructor': 'hacked'}) == 'hacked'


def test_dunder_bases_key_renders():
    assert render('{{obj.__bases__}}', {'obj': {'__bases__': 'hacked'}}) == 'hacked'


def test_dunder_reduce_key_renders():
    assert render('{{obj.__reduce__}}', {'obj': {'__reduce__': 'hacked'}}) == 'hacked'


def test_dunder_code_key_renders():
    assert render('{{obj.__code__}}', {'obj': {'__code__': 'hacked'}}) == 'hacked'


def test_dunder_builtins_key_renders():
    assert render('{{__builtins__}}', {'__builtins__': 'hacked'}) == 'hacked'


def test_dunder_via_each():
    """Dunder keys render normally in each loops."""
    assert render('{{#each items}}{{__class__}}{{/each}}', {'items': [{'__class__': 'ok'}]}) == 'ok'


# --- Serialization tests ---


def test_datetime_serialized():
    """datetime objects are serialized to ISO format strings."""
    dt = datetime(2024, 1, 15, 10, 30, 0)
    result = render('{{date}}', {'date': dt})
    assert '2024-01-15' in result


def test_callable_in_context_raises():
    """Callables in context raise serialization errors."""
    with pytest.raises(HandlebarsRuntimeError, match='Context serialization failed'):
        render('{{fn}}', {'fn': lambda: True})


def test_arbitrary_object_in_context_raises():
    """Arbitrary non-serializable objects raise serialization errors."""

    class Obj:
        name = 'safe'

    with pytest.raises(HandlebarsRuntimeError, match='Context serialization failed'):
        render('{{obj.name}}', {'obj': Obj()})


def test_nested_serialization():
    """Nested dicts with serializable values work."""
    result = render('{{obj.date}}', {'obj': {'date': datetime(2024, 1, 15)}})
    assert '2024-01-15' in result


# --- HTML escaping ---


def test_html_not_escaped_by_default():
    """HTML in values is not escaped by default (auto_escape=False)."""
    assert render('{{val}}', {'val': '<script>alert(1)</script>'}) == '<script>alert(1)</script>'


def test_html_injection_escaped_when_enabled():
    """HTML in values is escaped when auto_escape=True."""
    from pydantic_handlebars import HandlebarsEnvironment

    env = HandlebarsEnvironment(auto_escape=True)
    assert env.render('{{val}}', {'val': '<script>alert(1)</script>'}) == '&lt;script&gt;alert(1)&lt;/script&gt;'


def test_html_injection_not_escaped_with_triple():
    assert render('{{{val}}}', {'val': '<script>alert(1)</script>'}) == '<script>alert(1)</script>'

"""Tests for @data variables.

Ported from handlebars.js spec/data.js.
"""

from pydantic_handlebars import render

# --- @root ---


def test_at_root():
    assert render('{{@root.name}}', {'name': 'Alice'}) == 'Alice'


def test_at_root_in_nested_context():
    template = '{{#each items}}{{{@root.prefix}}}{{this}} {{/each}}'
    assert render(template, {'items': ['a', 'b'], 'prefix': '>'}) == '>a >b '


# --- @index ---


def test_at_index_in_each():
    assert render('{{#each items}}{{@index}} {{/each}}', {'items': ['a', 'b', 'c']}) == '0 1 2 '


# --- @key ---


def test_at_key_in_each_object():
    assert render('{{#each obj}}{{@key}}:{{this}} {{/each}}', {'obj': {'a': '1', 'b': '2'}}) == 'a:1 b:2 '


# --- @first and @last ---


def test_at_first():
    template = '{{#each items}}{{#if @first}}FIRST{{else}}other{{/if}} {{/each}}'
    assert render(template, {'items': [1, 2, 3]}) == 'FIRST other other '


def test_at_last():
    template = '{{#each items}}{{#if @last}}LAST{{else}}other{{/if}} {{/each}}'
    assert render(template, {'items': [1, 2, 3]}) == 'other other LAST '


# --- Nested @data ---


def test_nested_each_data():
    template = '{{#each outer}}{{#each inner}}{{@../index}}.{{@index}} {{/each}}{{/each}}'
    data = {'outer': [{'inner': ['a', 'b']}, {'inner': ['c', 'd']}]}
    assert render(template, data) == '0.0 0.1 1.0 1.1 '


# --- @data with parent ---


def test_at_root_in_deeply_nested():
    template = '{{#each a}}{{#each b}}{{@root.val}}{{/each}}{{/each}}'
    data = {'a': [{'b': [1]}], 'val': 'root'}
    assert render(template, data) == 'root'

"""Tests for block helpers and inverted sections.

Ported from handlebars.js spec/blocks.js.
"""

# pyright: reportUnknownVariableType=false

from typing import Any

from pydantic_handlebars import HandlebarsEnvironment, HelperOptions, render


def test_array_iteration():
    template = '{{#each goodbyes}}{{text}}! {{/each}}cruel {{world}}!'
    data = {
        'goodbyes': [{'text': 'goodbye'}, {'text': 'Goodbye'}, {'text': 'GOODBYE'}],
        'world': 'world',
    }
    assert render(template, data) == 'goodbye! Goodbye! GOODBYE! cruel world!'


def test_array_with_index():
    template = '{{#each array}}{{@index}}: {{this}} {{/each}}'
    assert render(template, {'array': ['a', 'b', 'c']}) == '0: a 1: b 2: c '


def test_empty_block():
    template = '{{#each items}}item{{/each}}'
    assert render(template, {'items': []}) == ''


def test_block_with_else():
    template = '{{#each items}}item{{else}}no items{{/each}}'
    assert render(template, {'items': []}) == 'no items'


def test_inverted_section_with_caret():
    """Test {{^}} as inverse shorthand."""
    template = '{{#if show}}visible{{^}}hidden{{/if}}'
    assert render(template, {'show': True}) == 'visible'
    assert render(template, {'show': False}) == 'hidden'


def test_block_with_complex_lookup():
    template = '{{#each people}}{{../greeting}} {{name}}! {{/each}}'
    data = {'people': [{'name': 'Alan'}, {'name': 'Yehuda'}], 'greeting': 'Hello'}
    assert render(template, data) == 'Hello Alan! Hello Yehuda! '


def test_nested_blocks():
    template = '{{#each outer}}[{{#each inner}}({{this}}){{/each}}]{{/each}}'
    data = {'outer': [{'inner': [1, 2]}, {'inner': [3, 4]}]}
    assert render(template, data) == '[(1)(2)][(3)(4)]'


def test_block_helper_with_inverse():
    env = HandlebarsEnvironment()

    def list_helper(context: object, *args: Any, options: HelperOptions) -> str:
        items = args[0] if args else None
        if isinstance(items, list) and items:
            return '<ul>' + ''.join(f'<li>{options.fn(item)}</li>' for item in items) + '</ul>'
        return options.inverse(context)

    env.register_helper('list', list_helper)
    assert (
        env.render(
            '{{#list items}}{{name}}{{else}}empty{{/list}}',
            {
                'items': [{'name': 'a'}, {'name': 'b'}],
            },
        )
        == '<ul><li>a</li><li>b</li></ul>'
    )
    assert (
        env.render(
            '{{#list items}}{{name}}{{else}}empty{{/list}}',
            {
                'items': [],
            },
        )
        == 'empty'
    )


def test_standalone_inverted_section():
    """Test {{^}} used inside blocks."""
    template = '{{#each items}}{{this}}{{^}}nothing{{/each}}'
    assert render(template, {'items': [1, 2, 3]}) == '123'
    assert render(template, {'items': []}) == 'nothing'


def test_block_parent_scope():
    template = '{{#with person}}{{name}} from {{../city}}{{/with}}'
    data = {'person': {'name': 'Alice'}, 'city': 'NYC'}
    assert render(template, data) == 'Alice from NYC'


def test_deeply_nested_parent_scope():
    template = '{{#each a}}{{#each b}}{{../../name}}{{/each}}{{/each}}'
    data = {'a': [{'b': [1]}], 'name': 'root'}
    assert render(template, data) == 'root'

"""Regression tests.

Ported from handlebars.js spec/regressions.js (relevant parts).
"""

# pyright: reportUnknownLambdaType=false, reportUnknownArgumentType=false

from pydantic_handlebars import HandlebarsEnvironment, render


def test_rendering_undefined_doesnt_crash():
    assert render('{{foo}}', {}) == ''


def test_rendering_null_doesnt_crash():
    assert render('{{foo}}', {'foo': None}) == ''


def test_if_with_empty_dict_is_truthy():
    """Empty dict should be truthy in Handlebars."""
    assert render('{{#if obj}}yes{{else}}no{{/if}}', {'obj': {}}) == 'yes'


def test_nested_undefined_path_doesnt_crash():
    assert render('{{foo.bar.baz}}', {}) == ''
    assert render('{{foo.bar.baz}}', {'foo': {}}) == ''
    assert render('{{foo.bar.baz}}', {'foo': {'bar': {}}}) == ''


def test_each_with_string_context():
    """Each should handle non-iterable gracefully."""
    assert render('{{#each val}}x{{else}}empty{{/each}}', {'val': 'string'}) == 'empty'


def test_with_false_context():
    """With should show else for falsy values."""
    assert render('{{#with val}}yes{{else}}no{{/with}}', {'val': False}) == 'no'
    assert render('{{#with val}}yes{{else}}no{{/with}}', {'val': None}) == 'no'
    assert render('{{#with val}}yes{{else}}no{{/with}}', {'val': ''}) == 'no'
    assert render('{{#with val}}yes{{else}}no{{/with}}', {'val': 0}) == 'no'


def test_if_with_dict_is_truthy():
    assert render('{{#if val}}yes{{else}}no{{/if}}', {'val': {'key': 'value'}}) == 'yes'


def test_multiple_comments():
    assert render('{{! one }}{{! two }}hello', {}) == 'hello'


def test_comment_inside_content():
    assert render('before{{! comment }}after', {}) == 'beforeafter'


def test_each_empty_body():
    assert render('{{#each items}}{{/each}}', {'items': [1, 2, 3]}) == ''


def test_nested_each_with_parent_context():
    template = '{{#each items}}{{#each sub}}{{../../name}}{{/each}}{{/each}}'
    data = {'items': [{'sub': [1]}], 'name': 'root'}
    assert render(template, data) == 'root'


def test_helper_with_string_arg():
    env = HandlebarsEnvironment()
    env.register_helper('echo', lambda *args, **kw: str(args[0]) if args else '')
    assert env.render('{{echo "hello world"}}', {}) == 'hello world'


def test_block_with_numeric_path_segment():
    """Closing block tag should accept NUMBER tokens in dot-notation paths."""
    template = '{{#items.0}}{{name}}{{/items.0}}'
    data = {'items': [{'name': 'first'}]}
    assert render(template, data) == 'first'


def test_block_with_slash_separator():
    """Closing block tag should preserve slash separators in path matching."""
    template = '{{#a/b}}{{c}}{{/a/b}}'
    data = {'a': {'b': {'c': 'yes'}}}
    assert render(template, data) == 'yes'


def test_block_with_slash_numeric_path():
    """Closing block tag should handle slash separators with numeric segments."""
    template = '{{#items/0}}{{name}}{{/items/0}}'
    data = {'items': [{'name': 'first'}]}
    assert render(template, data) == 'first'


def test_whitespace_in_expressions():
    assert render('{{  foo  }}', {'foo': 'bar'}) == 'bar'


def test_newline_in_expression():
    assert render('{{\nfoo\n}}', {'foo': 'bar'}) == 'bar'

"""Tests for custom built-in helpers.

Tests for json, uppercase, lowercase, trim, join, truncate,
eq, ne, gt, gte, lt, lte, and, or, not, default.

These are extra helpers that require ``extra_helpers=True``.
"""

import pytest

from pydantic_handlebars import HandlebarsEnvironment


@pytest.fixture
def env() -> HandlebarsEnvironment:
    return HandlebarsEnvironment(extra_helpers=True)


# --- json ---


def test_json_object(env: HandlebarsEnvironment):
    result = env.render('{{{json obj}}}', {'obj': {'a': 1}})
    assert result == '{"a": 1}'


def test_json_array(env: HandlebarsEnvironment):
    result = env.render('{{json arr}}', {'arr': [1, 2, 3]})
    assert result == '[1, 2, 3]'


def test_json_string(env: HandlebarsEnvironment):
    result = env.render('{{json val}}', {'val': 'hello'})
    assert result == '"hello"'


def test_json_string_unescaped(env: HandlebarsEnvironment):
    result = env.render('{{{json val}}}', {'val': 'hello'})
    assert result == '"hello"'


# --- uppercase ---


def test_uppercase(env: HandlebarsEnvironment):
    assert env.render('{{uppercase val}}', {'val': 'hello'}) == 'HELLO'


def test_uppercase_empty(env: HandlebarsEnvironment):
    assert env.render('{{uppercase val}}', {'val': ''}) == ''


# --- lowercase ---


def test_lowercase(env: HandlebarsEnvironment):
    assert env.render('{{lowercase val}}', {'val': 'HELLO'}) == 'hello'


# --- trim ---


def test_trim(env: HandlebarsEnvironment):
    assert env.render('{{trim val}}', {'val': '  hello  '}) == 'hello'


def test_trim_with_newlines(env: HandlebarsEnvironment):
    assert env.render('{{trim val}}', {'val': '\n hello \n'}) == 'hello'


# --- join ---


def test_join_basic(env: HandlebarsEnvironment):
    assert env.render('{{join arr ", "}}', {'arr': ['a', 'b', 'c']}) == 'a, b, c'


def test_join_default_separator(env: HandlebarsEnvironment):
