        render(
            '{{#each goodbyes}}{{text}}! {{/each}}cruel {{world}}!',
            {
                'goodbyes': [{'text': 'goodbye'}, {'text': 'Goodbye'}, {'text': 'GOODBYE'}],
                'world': 'world',
            },
        )
        == 'goodbye! Goodbye! GOODBYE! cruel world!'
